{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-skill-registry",
  "version": "0.3.0",
  "packageManager": "pnpm@12.11.2",
  "description": "OpenCode plugin that generates a lightweight per-project index of skills and convention files.",
  "license": "MIT",
  "type": "module",
  "main": "./dist/server.js",
  "exports": {
    ".": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "import": "./dist/server.js"
    }
  },
  "files": [
    "dist/",
    "README.md",
    "LICENSE",
    "NOTICE.md"
  ],
  "scripts": {
    "build": "node scripts/build.mjs && tsc -p tsconfig.build.json && node scripts/prune-declarations.mjs",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "bash scripts/test-skill-registry.sh && node tests/validate-pr-title.test.mjs && node tests/release-policy.test.mjs && node tests/package-publication.test.mjs && node tests/ci-workflow.test.mjs && node tests/publish-workflow.test.mjs && pnpm run test:install",
    "test:install": "node tests/clean-cache-install.test.mjs",
    "verify:package": "node scripts/verify-package.mjs",
    "verify:workflows": "node scripts/verify-workflow-actions.mjs",
    "security:audit": "pnpm audit --audit-level=low",
    "security:signatures": "node scripts/verify-registry-signatures.mjs",
    "security:check": "pnpm run security:audit && pnpm run security:signatures",
    "check": "pnpm run typecheck && pnpm run verify:workflows && pnpm run build && pnpm run test && pnpm run verify:package"
  },
  "engines": {
    "node": ">=22.0.0",
    "opencode": ">=2.0.28 <3"
  },
  "devDependencies": {
    "@opencode/cli": "2.0.28",
    "@opencode/client": "2.0.28",
    "@opencode/plugin": "2.0.28",
    "@types/node": "24.13.3",
    "esbuild": "0.28.1",
    "tsx": "4.23.5",
    "typescript": "5.9.3"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/andresnator/opencode-skill-registry.git"
  },
  "bugs": {
    "url": "https://github.com/andresnator/opencode-skill-registry/issues"
  },
  "homepage": "https://github.com/andresnator/opencode-skill-registry#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "skills",
    "registry",
    "agents"
  ]
}
